import time

import serial
from serial.serialutil import SerialException

from .connector import Connector


class SerialConnector(Connector):
    def __init__(self, port, baudrate=115200):
        super().__init__(port, baudrate)
        self._connection = None
        self._drain_timeout = 1.0

    def open(self, timeout=None):
        try:
            self._connection = serial.Serial(port=self.port, baudrate=self._baudrate, timeout=self._readline_timeout)
        except SerialException:
            raise ConnectionRefusedError(f"Could not open serial connection on port {self.port}. "
                                         f"Is someone already using it?")

    def is_closed(self):
        return self._connection is None or not self._connection.is_open

    def close(self):
        self._connection.close()

    def in_waiting(self):
        return self._connection.in_waiting

    def send_break(self):
        self._connection.send_break()

    def _read_one_line(self):
        return self._connection.read_until().decode('ascii', errors='backslashreplace')

    def read_available(self):
        """Read all available bytes from serial port without blocking."""
        if self._connection.in_waiting > 0:
            data = self._connection.read(self._connection.in_waiting)
            return data.decode("ascii", errors='backslashreplace')
        return ""

    def _send(self, cmd):
        self._connection.write(cmd.encode("ascii", errors='backslashreplace'))
        self._connection.flush()
        deadline = time.monotonic() + self._drain_timeout
        while self._connection.out_waiting > 0:
            if time.monotonic() > deadline:
                break
            time.sleep(0.001)
